20	/*!
21	 * \brief ub to ub copy
22	 * \param[in] src, Input LocalTensor
23	 * \param[out] dst, Output LocalTensor
24	 */
25	template <typename OperationShape, typename T>
26	__aicore__ inline void CopyAssign(
27	    AscendC::LocalTensor<T>& dst, const AscendC::LocalTensor<T>& src, OperationShape& operationShape)
28	{
29	    AscendC::DataCopy(dst, src, operationShape.axis0);
30	}
31	
32	/*!
33	 * \brief Datacopy from src to dst
34	 * \param[in] src, Input GlobalTensor
35	 * \param[in] copyCnt, Length of copy data
36	 * \param[out] dst, Output LocalTensor
37	 */
38	template <typename T>
39	__aicore__ inline void CopyIn(AscendC::LocalTensor<T> dst, AscendC::GlobalTensor<T> src, uint64_t copyCnt)
40	{
41	    AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(copyCnt * sizeof(T)), 0, 0, 0};
42	    AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
43	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
44	}
45	
46	/*!
47	 * \brief Datacopy from src to dst
48	 * \param[in] src, Input LocalTensor
49	 * \param[in] copyCnt, Length of copy data
50	 * \param[out] dst, Output GlobalTensor
51	 */
52	template <typename T>
53	__aicore__ inline void CopyOut(AscendC::GlobalTensor<T> dst, AscendC::LocalTensor<T> src, uint64_t copyCnt)
54	{
55	    AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(copyCnt * sizeof(T)), 0, 0, 0};
