11	#ifndef ATVOSS_INCLUDE_KERNEL_KERNEL_SCHEDULE_H_
12	#define ATVOSS_INCLUDE_KERNEL_KERNEL_SCHEDULE_H_
13	#include <functional>
14	#include "common/arch.h"
15	
16	#if !defined(__ATVOSS_HOST_ONLY__)
17	template <typename T>
18	using KernelTensor = AscendC::GlobalTensor<T>;
19	#else
20	template <typename T>
21	struct KernelTensor {
22	    using Type = T;
23	};
24	#endif
25	
26	namespace Atvoss::Ele {
27	
28	/*!
29	 * KernelBuilder: Calculate the tiling information, then determine the GM data that the current core needs to process
30	 * based on the block ID, and pass it to the block to complete the computation.
31	 */
32	template <typename BlockOp, const auto& Policy, typename ScheduleCfg>
33	class BaseKernelSchedule {
34	public:
35	    using ExprMaker = typename BlockOp::ScheduleClz::ExpressMaker;
36	    using ParamStruct = ScheduleCfg;
37	    using BlockTemplate = BlockOp;
38	    static constexpr auto EXPRESSION = ToLinearizerExpr(ExprMaker{}.template Compute<KernelTensor>());
39	    using Expr = typename decltype(EXPRESSION)::Type;
40	    using Params = Atvoss::Params_t<Expr>;
41	    using TileShape = typename BlockTemplate::BlockTileShape;
42	    using ArchTag = typename BlockOp::ScheduleClz::ArchTag;
43	    static constexpr uint64_t TILE_SHAPE_SIZE = TileShape::size::value;
44	    static constexpr uint64_t BASIC_BLOCK = BlockOp::ScheduleClz::BASIC_BLOCK;
45	    static constexpr uint64_t ALIGN_TILE_SHAPE_SIZE = 2;
46	    static constexpr uint64_t ACTUAL_N_ASSIGN =
47	        TILE_SHAPE_SIZE == 1 ? 32 : TileShape::template get_type<TILE_SHAPE_SIZE - 1>::value;
48	    static constexpr uint64_t BASIC_CORE_ELE_NUM =
49	        (BASIC_BLOCK + ACTUAL_N_ASSIGN - 1) / ACTUAL_N_ASSIGN * ACTUAL_N_ASSIGN;
50	
51	    /*!
52	     * \brief Kernel layer execution function.
53	     * \param[in] arguments, information of the user inputs.
54	     * \param[in] kernelParam, Tiling information in kernel.
55	     * \return bool. Return true to indicate param calculation success.
56	     */
57	    template <typename Args>
58	    static bool MakeScheduleConfig(const Args& arguments, ScheduleCfg& kernelParam)
59	    {
60	        // Extract input shape infomation from arguments
61	        using InputTuple = std::decay_t<decltype(std::get<0>(arguments))>;
62	        static_assert(std::tuple_size_v<InputTuple> > 0, "[ERROR]: [Atvoss][Kernel] Get input shape error \n");
63	        std::vector<uint64_t> shapeInfo = std::get<0>(std::get<0>(arguments)).shape_vector();
64	        uint64_t totalEleNum = CalculateTotalElements(shapeInfo);
65	
66	        if (shapeInfo.size() == 0 || totalEleNum == 0) {
67	            printf("[ERROR]: [Atvoss][Kernel] Shape info error \n");
68	            return false;
69	        }
70	
71	        kernelParam.unitNum = ACTUAL_N_ASSIGN;
72	        if (totalEleNum <= BASIC_CORE_ELE_NUM) {
73	            kernelParam.blockNum = 1;
74	            kernelParam.tailNum = totalEleNum;
75	            kernelParam.unitNumPerCore = 0;
76	            kernelParam.moreUnitCoreNum = 0;
77	            return true;
78	        }
79	
80	        uint64_t basicCoreUnitNum =
81	            BASIC_CORE_ELE_NUM / ACTUAL_N_ASSIGN; // Number of aligned units processable by a single core and
82	                                                  // basicCoreEleNum >= actualNAssign
83	        uint64_t totalUnitCnt = totalEleNum / ACTUAL_N_ASSIGN; // Total number of full units
84	        kernelParam.blockNum = (totalUnitCnt + basicCoreUnitNum - 1) / basicCoreUnitNum;
85	        if (kernelParam.blockNum > ArchTag::CORE_NUM) {
86	            kernelParam.blockNum = ArchTag::CORE_NUM;
87	        }
88	        kernelParam.unitNumPerCore = totalUnitCnt / kernelParam.blockNum;
89	        kernelParam.moreUnitCoreNum = totalUnitCnt % kernelParam.blockNum; // Number of remaining full units
90	        kernelParam.tailNum = totalEleNum % ACTUAL_N_ASSIGN;               // Remaining total elements
91	
92	        return true;
93	    }
94	
95	private:
96	    static inline uint64_t CalculateTotalElements(const std::vector<uint64_t>& shapeInfo)
97	    {
98	        uint64_t totalEleNum = 1;
99	        for (auto dim : shapeInfo) {
100	            totalEleNum *= dim;
101	        }
102	        return totalEleNum;
103	    }
104	
105	#if !defined(__ATVOSS_HOST_ONLY__)
106	public:
107	    /*!
108	     * \brief The constructor interface of KernelBuilder class.
109	     */
110	    __aicore__ inline BaseKernelSchedule() = default;
111	
112	    /*!
113	     * \brief Kernel layer execution function.
114	     * \param[in] cfg, Tiling information in kernel.
115	     * \param[in] argTuple, Input and output GM address.
116	     */
117	    template <typename OpParam, typename... Args>
118	    __aicore__ inline void Run(OpParam& cfg, Args... args)
119	    {
120	        // Configure block scheduling parameters
121	        typename BlockOp::ScheduleClz::ParamStruct configBlock = cfg.blockParam;
122	        configBlock.totalElemCnt = CalCurCoreEleCnt(cfg.kernelParam);
123	        // Pack and prepare arguments for kernel execution
124	        auto argTuple = AscendC::Std::forward_as_tuple(AscendC::Std::forward<Args>(args)...);
125	        auto params = PrepareParams<Params>(cfg.kernelParam, argTuple);
126	        auto convertArgs = ConvertArgs<Params>(params, argTuple);
127	
128	        BlockOp blockOp{};
129	        blockOp.Run(configBlock, convertArgs);
130	    }
131	
132	    template <typename Params, typename ArgTup>
133	    __aicore__ inline auto PrepareParams(ScheduleCfg& cfg, ArgTup& argTuple)
134	    {
135	        auto params =
136	            PrepareParamsImpl<Params>(cfg, argTuple, AscendC::Std::make_index_sequence<Atvoss::Util::Size_v<Params>>{});
137	        return params;
138	    }
139	
140	    __aicore__ inline auto CalCurCoreEleCnt(ScheduleCfg& cfg)
141	    {
142	        uint64_t blockNum = cfg.blockNum;
143	        uint64_t actualNum = cfg.unitNum * cfg.unitNumPerCore;
144	        if (AscendC::GetBlockIdx() < cfg.moreUnitCoreNum) {
145	            actualNum += cfg.unitNum;
146	        }
147	        if (AscendC::GetBlockIdx() == blockNum - 1) {
148	            actualNum += cfg.tailNum;
149	        }
150	        return actualNum;
151	    }
152	
153	    template <typename Params, typename ArgTup, std::size_t... Ints>
154	    __aicore__ inline auto PrepareParamsImpl(ScheduleCfg& config, ArgTup& args, AscendC::Std::index_sequence<Ints...>)
155	    {
156	        return AscendC::Std::make_tuple(ConstructParam<Atvoss::Util::Get_t<Params, Ints>>(config, args)...);
157	    }
158	
159	    template <typename ParamType, typename ArgTup>
160	    __aicore__ inline auto ConstructParam(ScheduleCfg& config, ArgTup& args)
161	    {
162	        auto arg = AscendC::Std::get<ParamType::number - 1>(args);
163	        if constexpr (!std::is_scalar_v<typename ParamType::Type>) {
164	            using DTypeTmp = typename ParamType::Type::PrimType;
165	            uint64_t offset = CalGMOffset(config);
166	            auto ptr = (uint64_t)(arg) + sizeof(DTypeTmp) * offset;
167	            return reinterpret_cast<__gm__ uint8_t*>(ptr);
168	        } else {
169	            using argType = decltype(arg);
170	            if constexpr (std::is_pointer_v<argType>) {
171	                return *arg;
172	            } else {
173	                return arg;
174	            }
175	        }
176	    }
177	
178	    template <typename Params, size_t Index, typename ParamTup, typename ArgTup>
179	    __aicore__ inline constexpr auto ConvertOneArg(ParamTup& params, ArgTup& args)
180	    {
181	        constexpr auto pos = Atvoss::Util::Find_v<Atvoss::CheckVarNum<Index + 1>::template Checker, Params>;
182	        if constexpr (pos < Atvoss::Util::Size_v<Params>) {
183	            return AscendC::Std::get<pos>(params);
184	        } else {
185	            return AscendC::Std::get<Index>(args);
186	        }
187	    }
188	
189	    template <typename Params, typename ParamTup, typename ArgTup, size_t... Ints>
190	    __aicore__ inline constexpr auto ConvertArgsImpl(
191	        ParamTup& params, ArgTup& args, AscendC::Std::index_sequence<Ints...>)
192	    {
193	        return AscendC::Std::make_tuple(ConvertOneArg<Params, Ints>(params, args)...);
194	    }
195	
196	    template <typename Params, typename ParamTup, typename ArgTup>
197	    __aicore__ inline auto ConvertArgs(ParamTup& params, ArgTup& args)
198	    {
199	        return ConvertArgsImpl<Params>(
200	            params, args, AscendC::Std::make_index_sequence<AscendC::Std::tuple_size_v<ArgTup>>{});
201	    }
202	
203	    __aicore__ inline auto CalGMOffset(ScheduleCfg& config)
204	    {
205	        if (AscendC::GetBlockIdx() < config.moreUnitCoreNum) {
206	            return AscendC::GetBlockIdx() * (config.unitNumPerCore * config.unitNum + config.unitNum);
207	        }
208	        return config.unitNumPerCore * config.unitNum * AscendC::GetBlockIdx() +
209	               config.moreUnitCoreNum * config.unitNum;
