161	template <typename T, typename... Ts>
162	struct CombineBufferWrapper<T, Ts...> {
163	    constexpr static uint32_t bufferId = static_cast<uint32_t>(T::bufferId) << (BUF_COMBINE_SHIFT * sizeof...(Ts)) |
164	                                         CombineBufferWrapper<Ts...>::bufferId;
165	    constexpr static uint32_t bufferUsage =
166	        T::bufferUsage << (BUF_COMBINE_SHIFT * sizeof...(Ts)) | CombineBufferWrapper<Ts...>::bufferUsage;
167	    constexpr static uint32_t pingPong =
168	        T::pingPong << (BUF_COMBINE_SHIFT * sizeof...(Ts)) | CombineBufferWrapper<Ts...>::pingPong;
169	    ;
