172	// Combined buffer wrapper template
173	template <typename... Ts>
174	struct CombinedBufferWrappers : BufferWrapper<
175	                                    static_cast<int>(
176	                                        static_cast<uint32_t>(sizeof...(Ts)) << (BUF_COMBINE_SHIFT * BUF_COMBINED_MAX) |
177	                                        CombineBufferWrapper<Ts...>::bufferId),
178	                                    CombineBufferWrapper<Ts...>::bufferUsage, CombineBufferWrapper<Ts...>::pingPong> {};
