271	template <
272	    typename InputOps, typename OpLst, typename ToReleaseLst, std::size_t currentOpPos, uint32_t bufferUsage,
273	    bool cacheBrc = false, uint32_t where = BUF_PING>
274	struct ReleaseBufferByUsageAux {};
275	
276	template <
277	    typename OpLst, typename ToReleaseLst, std::size_t currentOpPos, uint32_t bufferUsage, bool cacheBrc,
278	    uint32_t where>
279	struct ReleaseBufferByUsageAux<TypeList<>, OpLst, ToReleaseLst, currentOpPos, bufferUsage, cacheBrc, where> {
280	    using Type = TypeList<>;
281	};
