283	// Check & Release Buffer in TypeList<Head, Tail...>
284	template <
285	    typename Head, typename... Tail, typename OpLst, typename ToReleaseLst, std::size_t currentOpPos,
286	    uint32_t bufferUsage, bool cacheBrc, uint32_t where>
287	struct ReleaseBufferByUsageAux<
288	    TypeList<Head, Tail...>, OpLst, ToReleaseLst, currentOpPos, bufferUsage, cacheBrc, where> {
289	private:
290	    template <typename T>
291	    struct BufferUsageEqual : std::bool_constant<bufferUsage == T::bufferUsage && T::pingPong == where> {};
292	
293	    constexpr static bool ableToRelease = IsAbleToFree<OpLst, Head, cacheBrc, currentOpPos + 1>();
294	    // Find the Map of @Head in @ToReleaseLst
295	    using Mappings = MappingFind_t<ToReleaseLst, Head>;
296	    static_assert(Size_v<Mappings> == 1, "Mappings::Size == 1");
297	    // Find the buffer from the mapped buffers as per @bufferUsage
298	    using BufMapping = First_t<Mappings>;
299	    using Buffers = Filter_t<BufferUsageEqual, typename BufMapping::Buffers>;
300	    using Left = typename ReleaseBufferByUsageAux<
301	        TypeList<Tail...>, OpLst, ToReleaseLst, currentOpPos, bufferUsage, cacheBrc, where>::Type;
302	
303	public:
304	    using Type = Concatenate_t<std::conditional_t<ableToRelease, Buffers, TypeList<>>, Left>;
305	};
306	
307	// Release buffer in @ToReleaseLst as per usage @bufferUsage
308	template <
309	    typename OpLst, typename ToReleaseLst, std::size_t currentOpPos, uint32_t bufferUsage, bool cacheBrc = false,
310	    uint32_t where = BUF_PING>
311	struct ReleaseBufferByUsage {
312	    using Op = Get_t<OpLst, currentOpPos>;
313	    using InOps = typename Op::InNonScalarOps;
314	    using Type =
315	        typename ReleaseBufferByUsageAux<InOps, OpLst, ToReleaseLst, currentOpPos, bufferUsage, cacheBrc, where>::Type;
316	};
317	
318	// Collect unused input ops buffer in @InputOps from @ToReleaseLst
319	template <typename InputOps, typename OpLst, typename ToReleaseLst, std::size_t currentOpPos, bool cacheBrc>
320	struct ReleaseUnusedInputAux {};
321	
322	template <typename OpLst, typename ToReleaseLst, std::size_t currentOpPos, bool cacheBrc>
323	struct ReleaseUnusedInputAux<TypeList<>, OpLst, ToReleaseLst, currentOpPos, cacheBrc> {
324	    using Type = TypeList<>;
325	};
326	
327	template <
328	    typename Head, typename... Tail, typename OpLst, typename ToReleaseLst, std::size_t currentOpPos, bool cacheBrc>
329	struct ReleaseUnusedInputAux<TypeList<Head, Tail...>, OpLst, ToReleaseLst, currentOpPos, cacheBrc> {
330	private:
331	    constexpr static bool ableToRelease = IsAbleToFree<OpLst, Head, cacheBrc, currentOpPos + 1>();
332	    // Find @Head in @ToReleaseLst
333	    using Mappings = MappingFind_t<ToReleaseLst, Head>;
334	    static_assert(Size_v<Mappings> == 1, "Mappings::Size == 1");
335	    using Left = typename ReleaseUnusedInputAux<TypeList<Tail...>, OpLst, ToReleaseLst, currentOpPos, cacheBrc>::Type;
336	
337	public:
338	    using Type = Concatenate_t<std::conditional_t<ableToRelease, Mappings, TypeList<>>, Left>;
339	};
340	
341	// Remove unused input ops of OpX @currentOpPos from @ToReleaseLst
342	template <typename OpLst, typename ToReleaseLst, std::size_t currentOpPos, bool cacheBrc>
343	struct ReleaseUnusedInput {
344	    using Op = Get_t<OpLst, currentOpPos>;
345	    using InputOps = typename Op::InNonScalarOps;
346	    using NeedReleaseLst = typename ReleaseUnusedInputAux<InputOps, OpLst, ToReleaseLst, currentOpPos, cacheBrc>::Type;
347	    using Type = Difference_t<ToReleaseLst, NeedReleaseLst>;
348	};
349	
350	// Get first element from the first non-empty List.
351	template <typename T>
352	struct PriorityGetFirstAux {};
353	
354	template <typename T>
355	struct PriorityGetFirstAux<TypeList<T>> {
356	    using Type = First_t<T>;
357	};
358	
359	template <typename Head, typename... Tail>
360	struct PriorityGetFirstAux<TypeList<Head, Tail...>> {
361	    using Type =
362	        std::conditional_t<IsNotEmpty_v<Head>, First_t<Head>, typename PriorityGetFirstAux<TypeList<Tail...>>::Type>;
363	};
364	
365	template <typename... Ts>
366	struct PriorityGetFirst {
367	    static_assert(Any_v<IsNotEmpty, TypeList<Ts...>>, "At least one memory List should not be empty.");
368	    using Type = typename PriorityGetFirstAux<TypeList<Ts...>>::Type;
369	};
370	
371	template <typename... Ts>
372	using PriorityGetFirst_t = typename PriorityGetFirst<Ts...>::Type;
373	
374	// Pop the first element of @Ts if equals to @ToPop
375	template <typename Ts, typename ToPop, typename = void>
376	struct PopFrontIfEqual {
377	    using Type = Ts;
378	};
379	
380	template <typename Ts, typename ToPop>
381	struct PopFrontIfEqual<Ts, ToPop, std::enable_if_t<IsNotEmpty_v<Ts> && (std::is_same_v<First_t<Ts>, ToPop>)>> {
382	    using Type = RemoveFirstN_t<Ts, 1>;
383	};
384	
385	template <typename Ts, typename ToPop>
386	using PopFrontIfEqual_t = typename PopFrontIfEqual<Ts, ToPop>::Type;
387	
388	template <typename BufLstLst>
389	struct BufLstLstDecoder {
390	public:
391	    using PersistMte2Lst = Get_t<BufLstLst, static_cast<std::size_t>(BufPosInList::PERSIST_MTE2)>;
392	    using Mte2Lst = Get_t<BufLstLst, static_cast<std::size_t>(BufPosInList::MTE2)>;
393	    using PersistMte3Lst = Get_t<BufLstLst, static_cast<std::size_t>(BufPosInList::PERSIST_MTE3)>;
394	    using Mte3Lst = Get_t<BufLstLst, static_cast<std::size_t>(BufPosInList::MTE3)>;
395	    using PersistTmpLst = Get_t<BufLstLst, static_cast<std::size_t>(BufPosInList::PERSIST_TEMP)>;
396	    using TmpLst = Get_t<BufLstLst, static_cast<std::size_t>(BufPosInList::TEMP)>;
397	    using PongMte3Lst = Get_t<BufLstLst, static_cast<std::size_t>(BufPosInList::PONG_MTE3)>;
398	};
399	
400	template <typename BufLstLst, MemLevel memLvl, bool cache = false>
401	struct AllocMte2 {
402	private:
403	    using BufLsts = BufLstLstDecoder<BufLstLst>;
404	    // pop front
405	    using UsedTmpLst = std::conditional_t<memLvl == MemLevel::LEVEL_2 || cache, TypeList<>, typename BufLsts::TmpLst>;
406	    using UsedPongMte3Lst =
407	        std::conditional_t<memLvl != MemLevel::LEVEL_0 || cache, TypeList<>, typename BufLsts::PongMte3Lst>;
408	    using UsedPersistMte2Lst = std::conditional_t<!cache, TypeList<>, typename BufLsts::PersistMte2Lst>;
409	    using UsedMte2Lst = std::conditional_t<cache, TypeList<>, typename BufLsts::Mte2Lst>;
410	    using Mte2 = PriorityGetFirst_t<UsedPersistMte2Lst, UsedMte2Lst, UsedTmpLst, UsedPongMte3Lst>;
411	    // update
412	    using Mte2LstNext = PopFrontIfEqual_t<typename BufLsts::Mte2Lst, Mte2>;
413	    using TmpLstNext = PopFrontIfEqual_t<typename BufLsts::TmpLst, Mte2>;
414	    using PongMte3LstNext = PopFrontIfEqual_t<typename BufLsts::PongMte3Lst, Mte2>;
415	    using PersistMte2LstNext = PopFrontIfEqual_t<typename BufLsts::PersistMte2Lst, Mte2>;
416	
417	public:
418	    using Type = TypeList<
419	        PersistMte2LstNext, Mte2LstNext, typename BufLsts::PersistMte3Lst, typename BufLsts::Mte3Lst,
420	        typename BufLsts::PersistTmpLst, TmpLstNext, PongMte3LstNext, Mte2>;
421	};
422	
423	template <typename BufLstLst, MemLevel memLvl, bool cache = false>
424	using AllocMte2_t = typename AllocMte2<BufLstLst, memLvl, cache>::Type;
425	
426	template <typename BufLstLst, MemLevel memLvl, bool cache = false>
427	struct AllocTempBuffer {
428	private:
429	    using BufLsts = BufLstLstDecoder<BufLstLst>;
430	    // pop front
431	    using UsedPongMte3Lst =
432	        std::conditional_t<memLvl != MemLevel::LEVEL_0 || cache, TypeList<>, typename BufLsts::PongMte3Lst>;
433	    using UsedMte2Lst = std::conditional_t<memLvl == MemLevel::LEVEL_2 || cache, TypeList<>, typename BufLsts::Mte2Lst>;
434	    using UsedPersistTmpLst = std::conditional_t<!cache, TypeList<>, typename BufLsts::PersistTmpLst>;
435	    using UsedTmpLst = std::conditional_t<cache, TypeList<>, typename BufLsts::TmpLst>;
436	    using Tmp = PriorityGetFirst_t<UsedPersistTmpLst, UsedTmpLst, UsedPongMte3Lst, UsedMte2Lst>;
437	    // update
438	    using TmpLstNext = PopFrontIfEqual_t<typename BufLsts::TmpLst, Tmp>;
439	    using PongMte3LstNext = PopFrontIfEqual_t<typename BufLsts::PongMte3Lst, Tmp>;
440	    using Mte2LstNext = PopFrontIfEqual_t<typename BufLsts::Mte2Lst, Tmp>;
441	    using PersistTmpLstNext = PopFrontIfEqual_t<typename BufLsts::PersistTmpLst, Tmp>;
442	
443	public:
444	    using Type = TypeList<
445	        typename BufLsts::PersistMte2Lst, Mte2LstNext, typename BufLsts::PersistMte3Lst, typename BufLsts::Mte3Lst,
446	        PersistTmpLstNext, TmpLstNext, PongMte3LstNext, Tmp>;
447	};
448	
449	template <typename BufLstLst, MemLevel memLvl, bool cache = false>
450	using AllocTempBuffer_t = typename AllocTempBuffer<BufLstLst, memLvl, cache>::Type;
451	
452	template <typename BufLstLst, MemLevel memLvl, bool cache = false>
453	struct AllocMte3 {
454	private:
455	    using BufLsts = BufLstLstDecoder<BufLstLst>;
456	    // pop front
457	    using UsedTmpLst = std::conditional_t<memLvl != MemLevel::LEVEL_0 || cache, TypeList<>, typename BufLsts::TmpLst>;
458	    using UsedPongMte3Lst =
459	        std::conditional_t<memLvl != MemLevel::LEVEL_0 || cache, TypeList<>, typename BufLsts::PongMte3Lst>;
460	    using UsedMte2Lst = std::conditional_t<memLvl != MemLevel::LEVEL_0 || cache, TypeList<>, typename BufLsts::Mte2Lst>;
461	    using UsedPersistMte3Lst = std::conditional_t<!cache, TypeList<>, typename BufLsts::PersistMte3Lst>;
462	    using UsedMte3Lst = std::conditional_t<cache, TypeList<>, typename BufLsts::Mte3Lst>;
463	    using Mte3 = PriorityGetFirst_t<UsedPersistMte3Lst, UsedMte3Lst, UsedTmpLst, UsedPongMte3Lst, UsedMte2Lst>;
464	    // update
465	    using Mte3LstNext = PopFrontIfEqual_t<typename BufLsts::Mte3Lst, Mte3>;
466	    using TmpLstNext = PopFrontIfEqual_t<typename BufLsts::TmpLst, Mte3>;
467	    using PongMte3LstNext = PopFrontIfEqual_t<typename BufLsts::PongMte3Lst, Mte3>;
468	    using Mte2LstNext = PopFrontIfEqual_t<typename BufLsts::Mte2Lst, Mte3>;
469	    using PersistMte3LstNext = PopFrontIfEqual_t<typename BufLsts::PersistMte3Lst, Mte3>;
470	
471	public:
472	    using Type = TypeList<
473	        typename BufLsts::PersistMte2Lst, Mte2LstNext, PersistMte3LstNext, Mte3LstNext, typename BufLsts::PersistTmpLst,
474	        TmpLstNext, PongMte3LstNext, Mte3>;
475	};
476	
477	template <typename BufLstLst, MemLevel memLvl, bool cache = false>
478	using AllocMte3_t = typename AllocMte3<BufLstLst, memLvl, cache>::Type;
479	
480	// Release input buffers of OpX @opPos to @BufLstLst
481	// and remove from @ToReleaseLst
482	template <typename OpLst, typename BufLstLst, typename ToReleaseLst, bool cacheBrc, std::size_t opPos>
483	struct ReleaseAndUpdateLst {
484	private:
485	    using BufLsts = BufLstLstDecoder<BufLstLst>;
486	    // release & update
487	    using PersistMte2Lst = typename BufLsts::PersistMte2Lst;
488	    using Mte2LstNext = Concatenate_t<
489	        typename BufLsts::Mte2Lst, typename ReleaseBufferByUsage<OpLst, ToReleaseLst, opPos, BUF_MTE2, cacheBrc>::Type>;
490	    using PersistMte3Lst = typename BufLsts::PersistMte3Lst;
491	    using Mte3LstNext = Concatenate_t<
492	        typename BufLsts::Mte3Lst, typename ReleaseBufferByUsage<OpLst, ToReleaseLst, opPos, BUF_MTE3, cacheBrc>::Type>;
493	    using PersistTmpLst = typename BufLsts::PersistTmpLst;
494	    using TmpLstNext = Concatenate_t<
495	        typename BufLsts::TmpLst, typename ReleaseBufferByUsage<OpLst, ToReleaseLst, opPos, BUF_TEMP, cacheBrc>::Type>;
496	    using PongMte3LstNext = Concatenate_t<
497	        typename BufLsts::PongMte3Lst,
498	        typename ReleaseBufferByUsage<OpLst, ToReleaseLst, opPos, BUF_MTE3, cacheBrc, BUF_PONG>::Type>;
499	    // update ToReleaseLst to speedup next release
500	    using ToReleaseLstNext = typename ReleaseUnusedInput<OpLst, ToReleaseLst, opPos, cacheBrc>::Type;
501	
502	public:
503	    using Type = TypeList<
504	        PersistMte2Lst, Mte2LstNext, PersistMte3Lst, Mte3LstNext, PersistTmpLst, TmpLstNext, PongMte3LstNext,
505	        ToReleaseLstNext>;
506	};
507	
508	#if !defined(__ATVOSS_HOST_ONLY__)
509	template <typename TL, std::size_t N, BufType bt, int start = 0>
510	__aicore__ auto GetBufferId(bool isPing = true)
511	{
512	    if constexpr (start < Size_v<TL>) {
513	        using bufMap = Get_t<TL, start>;
514	        if constexpr (bufMap::paramNum == N && bufMap::bufType == bt) {
515	            return isPing ? bufMap::pingBufId : bufMap::pongBufId;
516	        } else {
517	            return GetBufferId<TL, N, bt, start + 1>(isPing);
518	        }
519	    } else {
520	        static_assert(start < Size_v<TL>, "Param or LocalVar Id invalid.");
521	    }
522	};
523	#endif
524	
525	/*
526	 * Generate buffer id of each Expression savedin @OpLst as per @memLvl
527	 * Template Arguments：
528	 *   1. OpLst: Ordered full Expression / Compute list
529	 *   2. OutLst: Full list of Output
530	 *   3. BufLstLst：Unused MTE2/MTE3/TmpBuffer List
531	 *   4. pongOffset: Offset of Pong buffer id to Ping buffer
532	 *   5. memLvl: memory level (policy) 0/1/2
533	 *   6. useNddma: whether use NDDMA from CopyInBrc operator
534	 *   7. cacheBrc: whether cache CopyInBrc & VecBrc operation outputs
535	 *   8. AllocLst: Allocated buffer list of `BufferWrapper` currently
536	 *   9. ToReleaseLst: To release list of `Mapping<Bind, TypeList<BufferWrapper...>>`
537	 *  10. scalarIdx: index or placehold of next `Scalar` operation output
538	 *  11. opPos: Position of current Expression / Compute
539	 * Return：
540	 *   1. 2*Size_v<OpLst> integer matrix as `const int32_t* const*`
541	 */
542	template <
543	    typename OpLst, typename OutLst, typename BufLstLst, uint32_t pongOffset, MemLevel memLvl = MemLevel::LEVEL_2,
544	    bool useNddma = true, bool cacheBrc = false, typename AllocLst = TypeList<>, typename ToReleaseLst = TypeList<>,
545	#ifdef __ATP_UT__
546	    int32_t scalarIdx = 50,
547	#else
548	    int32_t scalarIdx = 0,
549	#endif
550	    std::size_t opPos = 0>
551	static constexpr const int32_t* const* GenerateBufferIdOrder()
552	{
553	    if constexpr (opPos < Size_v<OpLst>) {
554	        using Op = Get_t<OpLst, opPos>;
555	        if constexpr (Op::isScalarOp) {
556	            using Buf = BufferWrapper<scalarIdx, BUF_SCALAR>;
557	            using AllocLstNext = Append_t<AllocLst, Buf>;
558	            return GenerateBufferIdOrder<
559	                OpLst, OutLst, BufLstLst, pongOffset, memLvl, useNddma, cacheBrc, AllocLstNext, ToReleaseLst,
560	                scalarIdx + 1, opPos + 1>();
561	        } else if constexpr (false /*IsBindOfOp_v<OpCopyInBrc, Op>*/ && !useNddma) { // TODO
562	            // use copyIn + ubBrc to implement nddma.
563	            using NextLst0 = AllocMte2_t<BufLstLst, memLvl, cacheBrc>;
564	            using Mte2 = Get_t<NextLst0, BUF_ALLOCATED_IDX>;
565	            if constexpr (ConnectToAny_v<OutLst, Op>) {
566	                // if CopyInBrc -> CopyOut, should use MTE3
567	                using NextLst = AllocMte3_t<NextLst0, memLvl, cacheBrc>;
568	                using Mte3 = Get_t<NextLst, BUF_ALLOCATED_IDX>;
569	                // add to alloc list
570	                using Buf = CombinedBufferWrappers<Mte3, Mte2>;
571	                using AllocLstNext = Append_t<AllocLst, Buf>;
572	                using ToReleaseLstNext = Append_t<ToReleaseLst, Mapping<Op, Mte3, Mte2>>;
573	                // next
574	                return GenerateBufferIdOrder<
575	                    OpLst, OutLst, NextLst, pongOffset, memLvl, useNddma, cacheBrc, AllocLstNext, ToReleaseLstNext,
576	                    scalarIdx, opPos + 1>();
577	            } else {
578	                using NextLst = AllocTempBuffer_t<NextLst0, memLvl, cacheBrc>;
579	                using Tmp = Get_t<NextLst, BUF_ALLOCATED_IDX>;
580	                // add to alloc list
581	                using Buf = CombinedBufferWrappers<Tmp, Mte2>;
582	                using AllocLstNext = Append_t<AllocLst, Buf>;
583	                using ToReleaseLstNext = Append_t<ToReleaseLst, Mapping<Op, Tmp, Mte2>>;
584	                // next
585	                return GenerateBufferIdOrder<
586	                    OpLst, OutLst, NextLst, pongOffset, memLvl, useNddma, cacheBrc, AllocLstNext, ToReleaseLstNext,
587	                    scalarIdx, opPos + 1>();
588	            }
589	        } else if constexpr (IsBindOfOp_v<OpCopyIn, Op>) {
590	            // activate cache when CopyInBrc = NDDMA
591	            using NextLst = AllocMte2_t<BufLstLst, memLvl, IsCacheBind_v<cacheBrc, Op>>;
592	            using Mte2 = Get_t<NextLst, BUF_ALLOCATED_IDX>;
593	            // add to alloc list
594	            using AllocLstNext = Append_t<AllocLst, Mte2>;
595	            using ToReleaseLstNext = Append_t<ToReleaseLst, Mapping<Op, Mte2>>;
596	            // next
597	            return GenerateBufferIdOrder<
598	                OpLst, OutLst, NextLst, pongOffset, memLvl, useNddma, cacheBrc, AllocLstNext, ToReleaseLstNext,
599	                scalarIdx, opPos + 1>();
600	        } else if constexpr (IsBindOfOp_v<OpCopyOut, Op>) {
601	            using NextLst = typename ReleaseAndUpdateLst<OpLst, BufLstLst, ToReleaseLst, cacheBrc, opPos>::Type;
602	            // release and update
603	            using ToReleaseLstNext = Get_t<NextLst, BUF_TO_RELEASE_IDX>;
604	            // fill -1 when no buffer is needed.
605	            using Buf = BufferWrapper<-1, BUF_PLACEHOLDER>;
606	            using AllocLstNext = Append_t<AllocLst, Buf>;
607	            // next
608	            return GenerateBufferIdOrder<
609	                OpLst, OutLst, NextLst, pongOffset, memLvl, useNddma, cacheBrc, AllocLstNext, ToReleaseLstNext,
610	                scalarIdx, opPos + 1>();
611	        } else {
612	            if constexpr (ConnectToAny_v<OutLst, Op>) {
613	                // activate cache when current Node is VecBrc
614	                using NextLst0 = AllocMte3_t<BufLstLst, memLvl, IsCacheBind_v<cacheBrc, Op>>;
615	                using Mte3 = Get_t<NextLst0, BUF_ALLOCATED_IDX>;
616	                // add to alloc list
617	                using AllocLstNext = Append_t<AllocLst, Mte3>;
618	                // release and update
619	                using NextLst = typename ReleaseAndUpdateLst<OpLst, NextLst0, ToReleaseLst, cacheBrc, opPos>::Type;
620	                using ToReleaseLstNext = Append_t<Get_t<NextLst, BUF_TO_RELEASE_IDX>, Mapping<Op, Mte3>>;
621	                // next
622	                return GenerateBufferIdOrder<
623	                    OpLst, OutLst, NextLst, pongOffset, memLvl, useNddma, cacheBrc, AllocLstNext, ToReleaseLstNext,
624	                    scalarIdx, opPos + 1>();
625	            } else {
626	                // activate cache when current Node is VecBrc
627	                using NextLst0 = AllocTempBuffer_t<BufLstLst, memLvl, IsCacheBind_v<cacheBrc, Op>>;
628	                using Tmp = Get_t<NextLst0, BUF_ALLOCATED_IDX>;
629	                // add to alloc list
630	                using AllocLstNext = Append_t<AllocLst, Tmp>;
631	                // release and update
632	                using NextLst = typename ReleaseAndUpdateLst<OpLst, NextLst0, ToReleaseLst, cacheBrc, opPos>::Type;
633	                using ToReleaseLstNext = Append_t<Get_t<NextLst, BUF_TO_RELEASE_IDX>, Mapping<Op, Tmp>>;
634	                // next
635	                return GenerateBufferIdOrder<
636	                    OpLst, OutLst, NextLst, pongOffset, memLvl, useNddma, cacheBrc, AllocLstNext, ToReleaseLstNext,
637	                    scalarIdx, opPos + 1>();
638	            }
639	        }
640	    } else {
641	        // generate buffer id list for ping-pong as per AllocLst.
642	        static_assert(Size_v<OpLst> == Size_v<AllocLst>, "Size_v<OpLst> == Size_v<AllocLst>");
643	        return ExtractBufferId<AllocLst, pongOffset>::Value;
644	    }
645	}
646	
647	} // namespace Atvoss::Ele::Tile
648	#endif // ATVOSS_ELEWISE_GRAPH_BUFFER_H

